def Make_Directory(Outpath):
    path=os.path.realpath(Outpath)
    directory = os.path.dirname(path)
    if not os.path.exists(directory):
        os.makedirs(directory)

def Download_CSC(ObsID):
    #print("__name__: ", __name__)
    if((__name__ == '__main__') or (__name__ == '__mp_main__')):
        #Outpath="./CSC_Data/"+str(ObsID)+"/"
        Outpath="./CSC_Data/"
        Make_Directory(Outpath)
        Outfile=str(ObsID)+".tsv"
        Outfilepath=Outpath+Outfile
        #print("Outfilepath: ", Outfilepath)
        with rt.new_pfiles_environment():
            Obsid_search_csc=rt.make_tool("obsid_search_csc")
            #obsid_search_csc obsid=635 outfile=635.tsv download=none mode=h
            #Dmcoords(infile=str(Empty_Filepath), theta=float(Theta), phi=float(Phi), option='msc', verbose=0, celfmt='deg')
            ##Obsid_search_csc(obsid=ObsID, outfile=str(Outfilepath), root=str(Outpath), download="none")
            #Obsid_search_csc(obsid=ObsID, outfile=str(Outfilepath), root=str(Outpath), bands="", download="none")
            punlearn("obsid_search_csc")
            pset("obsid_search_csc", "bands", "broad,soft,medium,hard,ultrasoft")
            plist("obsid_search_csc")
            Obsid_search_csc(obsid=ObsID, outfile=str(Outfilepath), root=str(Outpath), bands="broad,soft,medium,hard,ultrasoft", download="none", clobber="yes", verbose=5)
            #Obsid_search_csc(obsid=ObsID, outfile=str(Outfilepath), root=str(Outpath), bands="ultrasoft", download="none")
            #obsid_search_csc(obsid=ObsID, outfile=str(Outfilepath), root=str(Outpath), bands="broad,soft,medium,hard,ultrasoft", download="none", clobber="yes", verbose=5)


def Driver(Func, Array):
    if __name__ == '__main__':
        P = Pool()
        P.map(Func, Array)

def Download_CSC_Driver(ObsID_L):
    Driver(Download_CSC, ObsID_L)

def Download_CSC_2(ObsID):
    Outpath="./CSC_Data/"
    Make_Directory(Outpath)
    Outfile=str(ObsID)+".tsv"
    Outfilepath=Outpath+Outfile
    #Command="obsid_search_csc obsid="+str(ObsID)+" outfile="+str(Outfilepath)+" root="+str(Outpath)+" bands='broad,soft,medium,hard,ultrasoft' download=none"
    Command="obsid_search_csc obsid="+str(ObsID)+" outfile="+str(Outfilepath)+" root="+str(Outpath)+" bands='broad,soft,medium,hard,ultrasoft' download=none clobber=yes verbose=5"
    #print("Command: ", Command)
    os.system(Command)

